def is_palindrome(value: str) -> bool:
    left, right = 0, len(value) - 1
    while left < right:
        while left < right and not value[left].isalnum():
            left += 1
        while left < right and not value[right].isalnum():
            right -= 1
        if value[left].lower() != value[right].lower():
            return False
        left += 1
        right -= 1
    return True
